package com.projectedith.alert

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

class CodesTest {
    // Generated by the Worker (worker/test/codes.test.js) for secret
    // "test-secret-please-change" and name "Sara". Both sides must agree.
    private val code = "9Q87-5BDV-D95Q-8MSM"
    private val topic = "edith-9be91b25fc2cff545acd04de5e92b95401762f65fea40d28632b8896bf452b3d"

    @Test
    fun matchesWorkerVector() {
        assertTrue(Codes.isValid(code))
        assertEquals(topic, Codes.topic(code))
    }

    @Test
    fun forgivesFormatting() {
        val messy = " 9q87 5bdv-d95q 8msm "
        assertTrue(Codes.isValid(messy))
        assertEquals(topic, Codes.topic(messy))
        assertEquals(code, Codes.format(messy))
        assertEquals("0111", Codes.normalize("oIl1"))
    }

    @Test
    fun rejectsTyposAndJunk() {
        assertFalse(Codes.isValid("9Q87-5BDV-D95Q-8MSN"))
        assertFalse(Codes.isValid("9Q87-5BDV-D95Q"))
        assertFalse(Codes.isValid("hello"))
    }
}
